128	    @Override
129	    public NotifyTaskJudgeStatusVO queryNotifyTaskJudgeStatus(NotifyTaskJudgeStatusItemParam param) {
130	        if (param == null || param.getTaskDispatchId() == null) {
131	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL,
132	                    "taskDispatchId不能为空");
133	        }
134	
135	        // 按任务id查询待通知复尺节点，项目/品类/任务类型以查询结果为准。
136	        TaskDispatchParam taskDispatchParam = TaskDispatchParam.builder()
137	                .taskDispatchIds(Collections.singletonList(param.getTaskDispatchId()))
138	                .nodeType(NOTIFY_NODE_TYPE)
139	                .taskType(DEFAULT_TASK_TYPE)
140	                .processStatus(ProcessStatusEnum.UNFINISHED.getValue())
141	                .build();
142	        List<TaskDispatchDTO> taskList = taskDispatchNodeDao.listTaskByCondition(taskDispatchParam);
143	        if (CollectionUtils.isEmpty(taskList)) {
144	            logger.info("queryNotifyTaskJudgeStatus empty task, taskDispatchId={}", param.getTaskDispatchId());
145	            return NotifyTaskJudgeStatusVO.builder()
146	                    .materialCodes(Collections.emptyList())
147	                    .judgeResult(NOT_JUDGED)
148	                    .recognized(NOT_RECOGNIZED)
149	                    .categoryMatched(false)
150	                    .build();
151	        }
152	        TaskDispatchDTO task = taskList.get(0);
153	
154	        // 开城品类code列表：自动通知开关配置的品类全集（即 categoryMatched 的判定全集）。
155	        Map<String, NotifyAutomationConfig.DimensionRule> autoNotifyRules = notifyAutomationConfig.parseAutoNotifyRules();
156	        NotifyTaskJudgeStatusVO result = NotifyTaskJudgeStatusVO.builder()
157	                .taskDispatchNodeId(task.getTaskDispatchNodeId())
158	                .materialCodes(Collections.singletonList(task.getMaterialCode()))
159	                .judgeResult(NOT_JUDGED)
160	                .recognized(NOT_RECOGNIZED)
161	                .categoryMatched(false)
162	                .build();
163	        // 先过品类校验：未命中通知复尺配置的品类不查识别表，recognized/judgeResult 保持 0（未判定）。
164	        // 与执行记录的品类口径一致，仅判断配置中是否存在该品类。
165	        boolean categoryMatched = autoNotifyRules.containsKey(task.getMaterialCode());
166	        result.setCategoryMatched(categoryMatched);
167	        if (!categoryMatched) {
168	            return result;
169	        }
170	
171	        // 识别表无节点id，按项目/品类/任务类型精确维度查询，避免不同任务类型串数据。
172	        // 不传notifyExecuteType，不限制判定结果、执行状态和识别日期；取识别结果表最新一条的判定值。
173	        Map<String, MaterialNotifyTaskAutomation> recognition =
174	                queryLatestNotifyUnDoneByDimension(Collections.singletonList(task), task.getTaskType());
175	        MaterialNotifyTaskAutomation recognizeResult =
176	                recognition.get(dimensionKey(task.getProjectOrderId(), task.getMaterialCode()));
177	        if (recognizeResult == null) {
178	            return result;
179	        }
180	        // 有识别记录即已判定：recognized=1；判定值原样透出，表里为空按 5（无结果）兜底。
181	        result.setRecognized(RECOGNIZED);
182	        result.setJudgeResult(recognizeResult.getJudgeResult() == null
183	                ? NotifyJudgeResultEnum.NONE_RESULT.getValue()
184	                : recognizeResult.getJudgeResult().intValue());
185	        return result;
186	    }
