3	import com.fasterxml.jackson.core.type.TypeReference;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import lombok.Data;
6	import lombok.extern.slf4j.Slf4j;
7	import org.springframework.beans.factory.annotation.Value;
8	import org.springframework.stereotype.Service;
9	import org.springframework.util.CollectionUtils;
10	import org.springframework.util.StringUtils;
11	
12	import javax.annotation.Resource;
13	import java.io.IOException;
14	import java.util.Collections;
15	import java.util.List;
16	import java.util.Map;
17	
18	/**
19	 * 通知复尺自动化配置（Apollo JSON）。
20	 *
21	 * <p>开关A：功能开关（城市 OR 工长 OR 工程部 → 放行），接点在 batch/query 列表过滤。
22	 * 开关B：自动通知开关（品类 → 各一套规则），接点留给自动通知功能开发时接入。
23	 * fail-closed：配置缺失/非法/入参为空 → 不命中。
24	 */
25	@Service
26	@Slf4j
27	public class NotifyAutomationConfig {
28	
29	    /** 开关A：功能开关 */
30	    @Value("${notification.remeasure.automation.open:{}}")
31	    private String featureOpenConfig;
32	
33	    /** 开关B：自动通知（品类码 → 各一套 城市/工长/工程部 规则） */
34	    @Value("${notification.remeasure.automation.autoNotify:{}}")
35	    private String autoNotifyConfig;
36	
37	    @Resource
38	    private ObjectMapper objectMapper;
39	
40	    /** 功能开关：gbCode∈cities OR foremanUcid∈projectManagers OR departmentCode∈departments */
41	    public boolean isFeatureOpen(String gbCode, String foremanUcid, String departmentCode) {
42	        DimensionRule rule = parseFeatureOpenRule();
43	        return rule != null && rule.hit(gbCode, foremanUcid, departmentCode);
44	    }
45	
46	    /** 自动通知开关（按品类）：该品类三集 OR */
47	    public boolean isAutoNotifyOpen(String materialCode, String gbCode, String foremanUcid, String departmentCode) {
48	        if (StringUtils.isEmpty(materialCode)) {
49	            return false;
50	        }
51	        Map<String, DimensionRule> rules = parseAutoNotifyRules();
52	        DimensionRule rule = rules.get(materialCode);
53	        return rule != null && rule.hit(gbCode, foremanUcid, departmentCode);
54	    }
55	
56	    private DimensionRule parseFeatureOpenRule() {
57	        try {
58	            return objectMapper.readValue(featureOpenConfig, DimensionRule.class);
59	        } catch (IOException e) {
60	            log.warn("解析通知复尺自动化功能开关配置失败: {}", featureOpenConfig, e);
61	            return null;
62	        }
63	    }
64	
65	    public Map<String, DimensionRule> parseAutoNotifyRules() {
66	        try {
67	            Map<String, DimensionRule> rules = objectMapper.readValue(autoNotifyConfig,
68	                    new TypeReference<Map<String, DimensionRule>>() {});
69	            return rules == null ? Collections.emptyMap() : rules;
70	        } catch (IOException e) {
71	            log.warn("解析通知复尺自动化自动通知开关配置失败: {}", autoNotifyConfig, e);
72	            return Collections.emptyMap();
73	        }
74	    }
75	
76	    @Data
77	    public static class DimensionRule {
78	        private List<String> cities;
79	        private List<String> projectManagers;
80	        private List<String> departments;
81	
82	        public boolean hit(String gbCode, String foremanUcid, String departmentCode) {
83	            return inList(cities, gbCode)
84	                    || inList(projectManagers, foremanUcid)
85	                    || inList(departments, departmentCode);
86	        }
87	
88	        private boolean inList(List<String> list, String value) {
89	            return !CollectionUtils.isEmpty(list) && !StringUtils.isEmpty(value) && list.contains(value);
90	        }
91	    }
92	}
