398	    private NotifyTaskDetailVO buildDetail(TaskDispatchDTO task, MaterialNotifyTaskAutomation auto, Map<Long, ProjectOrderDetailBO> projectOrderMap) {
399	        NotifyTaskDetailVO vo = new NotifyTaskDetailVO();
400	        vo.setProjectOrderId(String.valueOf(task.getProjectOrderId()));
401	        if (projectOrderMap.containsKey(task.getProjectOrderId())) {
402	            vo.setProjectAddress(projectOrderMap.get(task.getProjectOrderId()).getAddress());
403	        }
404	        vo.setTaskDispatchNodeId(task.getTaskDispatchNodeId());
405	        vo.setTaskDispatchId(task.getTaskDispatchId());
406	        vo.setBusinessId(task.getBusinessId());
407	        vo.setMaterialCode(task.getMaterialCode());
408	        vo.setMaterialName(task.getMaterialName());
409	        vo.setSupplierName(task.getSupplierName());
410	        vo.setTaskType(task.getTaskType());
411	        vo.setNodeType(task.getNodeType());
412	        vo.setTaskNodeName(NodeTypeEnum.getAliasName(task.getNodeType(), TaskTypeEnum.getNameByValue(task.getTaskType())));
413	        vo.setEstimatedTime(task.getEstimatedTime());
414	        // 期望上门时间/图片优先取 node，空则取 automation（通知结果表）兜底
415	        if (auto != null) {
416	            vo.setRecommendVisitTime(auto.getRecommendVisitTime());
417	            vo.setJudgeResult(auto.getJudgeResult().intValue());
418	            vo.setJudgeReason(auto.getJudgeRemark());
419	            vo.setImages(splitImages(auto.getImages()));
420	        }
421	        // Node 数据优先，有值才覆盖 Automation Node时间小于2000年也不能用
422	        Calendar calendar = Calendar.getInstance();
423	        calendar.setTime(task.getNoticeRetainTime());
424	        if (calendar.get(Calendar.YEAR) >= 2010) {
425	            vo.setRecommendVisitTime(task.getNoticeRetainTime());
426	        }
427	        if (!StringUtils.isEmpty(task.getImages())) {
428	            vo.setImages(splitImages(task.getImages()));
429	        }
430	        return vo;
431	    }
