391	    private List<Date> calcDateRange(Date date, Integer days) {
392	        Calendar calendar = Calendar.getInstance();
393	        calendar.setTime(date);
394	        calendar.add(Calendar.DATE, days);
395	
396	        calendar.set(Calendar.AM_PM, 0);
397	        calendar.set(Calendar.HOUR, 0);
398	        calendar.set(Calendar.MINUTE, 0);
399	        calendar.set(Calendar.SECOND, 0);
400	        Date startDate = calendar.getTime();
401	
402	        calendar.add(Calendar.DATE, 1);
403	        calendar.add(Calendar.SECOND, -1);
404	        Date endDate = calendar.getTime();
405	
406	        return Lists.newArrayList(startDate, endDate);
407	    }
