590	            TemplateParserContext parserContext = new TemplateParserContext();
591	            StandardEvaluationContext context = new StandardEvaluationContext();
592	            context.setVariable("messagePushClient",this);
593	            context.setVariable("taskDispatch",taskDispatch);
594	            context.setVariable("taskDispatchNode",node);
595	            ProjectOrderDetailBO orderInfoDTO = projectOrderManager.getProjectOrder(node.getProjectOrderId());
596	            context.setVariable("projectOrderInfo",orderInfoDTO);
597	            context.setVariable("esTime", DateUtils.format(node.getEstimatedTime(),DateUtils.DEFAULT_DAY_FORMAT));
598	
599	
600	            Config config = ConfigService.getConfig("message");
601	            String jumpUrl = config.getProperty(taskNodeMsgEnum.getJumpUrlKey(), "");
602	
603	            TaskMessageParam messageParam = TaskMessageParam.builder()
604	                .title(parser.parseExpression(taskNodeMsgEnum.getTitle(), parserContext).getValue(context,String.class))
605	                .content(parser.parseExpression(taskNodeMsgEnum.getMsgContent(), parserContext).getValue(context,String.class))
606	                .url(parser.parseExpression(jumpUrl, parserContext).getValue(context, String.class))
607	                .channel(taskNodeMsgEnum.getPushChannelEnum().getCode()).build();
608	
609	            String receiverId = node.getExecutorId();
610	            if (!StringUtils.isEmpty(taskNodeMsgEnum.getReceiverUcIds())){
611	                receiverId = parser.parseExpression(taskNodeMsgEnum.getReceiverUcIds(),parserContext).getValue(context,String.class);
612	            }
613	
614	            if (StringUtils.isEmpty(receiverId)){
615	                logger.info("receiverUcId  is null.taskDispatch:{},TaskDispatchNode:{},taskNodeMsgEnum:{}",taskDispatch,node,taskNodeMsgEnum);
616	                return;
617	            }
618	            HashSet<String> receiverSet = Sets.newHashSet(receiverId);
619	
620	            ProjectOrderDto orderDto = orderInfoDTO.getOrderDto();
621	            // 仅需处理2.5的订单
622	            if (TaskTypeEnum.getPushAdvisorList().contains(taskDispatch.getTaskType()) &&
623	                    ProjectOrderUtil.isBeiJingV2_5(orderDto.getProcessVersion(), orderDto.getBusinessModel())) {
624	                if (TASK_NODE_ENUM_LIST_2_5.contains(taskNodeMsgEnum.name())) {
625	                    return;
626	                }
627	                // 2.5 增加家居顾问
628	                List<String> homeAdvisorList = getHomeAdvisorList(taskDispatch, orderInfoDTO);
629	                if (!CollectionUtils.isEmpty(homeAdvisorList)) {
630	                    receiverSet.addAll(homeAdvisorList);
631	                }
632	            }
633	            if (PushChannelEnum.supportMessage(taskNodeMsgEnum.getPushChannelEnum())){
634	                pushClient.sendPushMsg(receiverSet, messageParam);
635	            }
636	
637	            // 发短信
638	            if (canPushNotice && PushChannelEnum.supportNotice(taskNodeMsgEnum.getPushChannelEnum())){
639	                // 先将receiverUcId转成phone
640	                String receiverPhone = getReceiverPhone(orderInfoDTO,receiverId);
641	                if (StringUtils.isEmpty(receiverPhone)){
642	                    logger.info("receiverPhone  is null.taskDispatch:{},TaskDispatchNode:{},taskNodeMsgEnum:{}",taskDispatch,node,taskNodeMsgEnum);
643	                    return;
644	                }
645	                pushClient.sendPushNotice(Sets.newHashSet(receiverPhone),messageParam);
646	
647	            }
648	        }catch (Exception e){
649	            logger.error("push message error.taskDispatch:{},TaskDispatchNode:{},taskNodeMsgEnum:{}",taskDispatch,node,taskNodeMsgEnum,e);
650	        }
651	
652	    }
