726	    public void pushMessageWhenRecheckRejected(TaskDispatch taskDispatch, TaskDispatchNode rejectNode, List<TaskDispatchNode> notifyNodes) {
727	        if (taskDispatch == null || rejectNode == null || CollectionUtils.isEmpty(notifyNodes)) {
728	            return;
729	        }
730	        // 仅对测量/复尺任务发送
731	        if (!TaskTypeEnum.RECHECK_SCALE.getValue().equals(taskDispatch.getTaskType())
732	                && !TaskTypeEnum.MEASURE.getValue().equals(taskDispatch.getTaskType())) {
733	            return;
734	        }
735	        try {
736	            ProjectOrderDetailBO orderInfoDTO = projectOrderManager.getProjectOrder(rejectNode.getProjectOrderId());
737	            String address = orderInfoDTO.getAddress();
738	            String materialName = taskDispatch.getMaterialName();
739	            String taskTypeName = TaskTypeEnum.getNameByValue(taskDispatch.getTaskType());
740	
741	            // 驳回人信息（执行节点的执行人）
742	            String rejectRoleName = RoleTypeEnum.getNameByValue(rejectNode.getExecutorType() == null ? null : rejectNode.getExecutorType().intValue());
743	            String rejectPersonName = StringUtils.isEmpty(rejectNode.getExecutorName()) ? "" : rejectNode.getExecutorName();
744	            String rejectRolePrefix = StringUtils.isEmpty(rejectRoleName) ? "" : rejectRoleName + "-";
745	
746	            for (TaskDispatchNode notifyNode : notifyNodes) {
747	                if (StringUtils.isEmpty(notifyNode.getExecutorId())) {
748	                    logger.info("pushMessageWhenRecheckRejected notifyNode executorId is empty, notifyNodeId={}", notifyNode.getId());
749	                    continue;
750	                }
751	                // 通知节点执行人信息
752	                String notifyRoleName = RoleTypeEnum.getNameByValue(notifyNode.getExecutorType() == null ? null : notifyNode.getExecutorType().intValue());
753	                String notifyPersonName = StringUtils.isEmpty(notifyNode.getExecutorName()) ? "" : notifyNode.getExecutorName();
754	                String notifyRolePrefix = StringUtils.isEmpty(notifyRoleName) ? "" : notifyRoleName + "-";
755	
756	                String title = String.format(MEASURE_REJECTED_TITLE, notifyRolePrefix, notifyPersonName, taskTypeName);
757	                String content = String.format(MEASURE_REJECTED_CONTENT,
758	                        notifyRolePrefix, notifyPersonName,
759	                        rejectRolePrefix, rejectPersonName,
760	                        materialName, taskTypeName, address);
761	                String url = buildRejectedJumpUrl(taskDispatch, notifyNode);
762	
763	                TaskMessageParam messageParam = TaskMessageParam.builder()
764	                        .title(title)
765	                        .content(content)
766	                        .url(url)
767	                        .channel(PushChannelEnum.GONGZUOZHUSHOU.getCode())
768	                        .build();
769	
770	                logger.info("pushMessageWhenRecheckRejected param={}, notifyExecutorId={}", messageParam, notifyNode.getExecutorId());
771	                pushClient.sendPushMsg(Sets.newHashSet(notifyNode.getExecutorId()), messageParam);
772	            }
773	        } catch (Exception e) {
774	            logger.error("pushMessageWhenRecheckRejected error, taskDispatch={}, rejectNode={}", taskDispatch, rejectNode, e);
775	        }
776	    }
