801	    /**
802	     * 配置可能包含页面路径（如 /pages/main-material-form），这里统一归一到域名，避免拼出错误路由。
803	     */
804	    private String normalizeHomeBaseUrl(String rawBaseUrl) {
805	        if (StringUtils.isEmpty(rawBaseUrl)) {
806	            return "";
807	        }
808	        try {
809	            URI uri = URI.create(rawBaseUrl);
810	            if (StringUtils.isEmpty(uri.getScheme()) || StringUtils.isEmpty(uri.getHost())) {
811	                return rawBaseUrl;
812	            }
813	            StringBuilder builder = new StringBuilder(uri.getScheme()).append("://").append(uri.getHost());
814	            if (uri.getPort() > 0) {
815	                builder.append(":").append(uri.getPort());
816	            }
817	            return builder.toString();
818	        } catch (Exception e) {
819	            logger.warn("normalizeHomeBaseUrl invalid rawBaseUrl={}, use as-is", rawBaseUrl, e);
820	            return rawBaseUrl;
821	        }
822	    }
