120	    private void sendPushGroupMsg(PushGroupSendParam pushGroupSendParam, PushConfigProperties pushConfigProperties) {
121	        try {
122	            // 传0会报错，接收用户类型非法:0
123	            if (StringUtils.isEmpty(pushGroupSendParam.getTo_ucids())
124	                    || Objects.equals(pushGroupSendParam.getTo_ucids(), "0")
125	                    || Objects.equals(pushGroupSendParam.getTo_ucids(), "1000000001")
126	                    || Objects.equals(pushGroupSendParam.getTo_ucids(), "1000000003")) {
127	                return;
128	            }
129	            CompletableFuture.runAsync(() -> {
130	                String responseMsg = pushHttpUtil.postJson(pushConfigProperties.getUrl(), ObjectUtils.objectToMap(pushGroupSendParam), pushConfigProperties);
131	                logger.info("发送push消息, sendPushGroupSendParam{}，发送地址{}", pushGroupSendParam, pushConfigProperties.getUrl());
132	                if (StringUtils.isNotBlank(responseMsg)) {
133	                    PushDTO pushDTO = JSON.parseObject(responseMsg, PushDTO.class);
134	                    if (0 != pushDTO.getErrno()) {
135	                        String errorMsg = pushDTO.getError();
136	                        throw new UtopiaBussinessException(ResultCodeEnum.ERROR_INVOKE, errorMsg);
137	                    }
