139	    @Override
140	    public void processDelayMessage(MessageSendJob sendJob) {
141	        TaskDispatchNode taskDispatchNode = taskDispatchNodeDao.getById(sendJob.getTaskDispatchNodeId());
142	        if(taskDispatchNode == null) {
143	            log.info("taskDispatchNode is null, taskDispatchNodeId:{}", sendJob.getTaskDispatchNodeId());
144	            updateMessageState(sendJob, MessageRunStateEnum.FAIL);
145	            return ;
146	        }
147	        if(ProcessStatusEnum.FINISHED.getValue().equals(taskDispatchNode.getProcessStatus().intValue())) {
148	            log.info("taskDispatchNode is finished, taskDispatchNodeId:{}", sendJob.getTaskDispatchNodeId());
149	            updateMessageState(sendJob, MessageRunStateEnum.FAIL);
150	            return ;
151	        }
152	        // check time
153	        // 判断考核时间是正常的
154	        if(MIN_DATE.compareTo(taskDispatchNode.getEstimatedTime()) > 0) {
155	            log.info("非有效时间, taskDispatchNodeId:{}，time:{}", sendJob.getTaskDispatchNodeId(), taskDispatchNode.getEstimatedTime());
156	            return ;
157	        }
158	        long l ;
159	        if(NoticeTimeTypeEnum.WILL_DELAY.getValue().equals(sendJob.getNoticeTimeType())) {
160	            l = taskDispatchNode.getEstimatedTime().getTime() - sendJob.getBeforeTimes();
161	        } else {
162	            l = taskDispatchNode.getEstimatedTime().getTime() + sendJob.getBeforeTimes();
163	        }
164	        Date sendDate = new Date(l);
165	        // 发送时间在当天之前，不发送
166	        if(sendDate.before(new Date())) {
167	            updateMessageState(sendJob, MessageRunStateEnum.FAIL);
168	            return ;
169	        }
170	        if(!DateUtil.isToday(sendDate)) {
171	            return ;
172	        }
173	        NMaterialTaskForm taskForm = getTaskForm(taskDispatchNode);
174	        if(taskForm == null) {
175	            log.info("taskForm is null, taskDispatchNodeId:{}", sendJob.getTaskDispatchNodeId());
176	            updateMessageState(sendJob, MessageRunStateEnum.FAIL);
177	            return ;
178	        }
179	        if(CollectionUtils.isEmpty(taskForm.getMaterialPushCfgList())) {
180	            log.info("materialPushCfgList is empty, taskDispatchNodeId:{}", sendJob.getTaskDispatchNodeId());
181	            updateMessageState(sendJob, MessageRunStateEnum.FAIL);
182	            return ;
183	        }
184	        List<NMaterialPushCfg> collect = taskForm.getMaterialPushCfgList().stream()
185	            .filter(t ->
186	                sendJob.getNoticeTimeType().equals(t.getNoticeTimeType()))
187	            .filter(t ->
188	                sendJob.getNoticeMoment().equals(t.getNoticeMoment())).collect(Collectors.toList());
189	        if(CollectionUtils.isEmpty(collect)) {
190	            log.info("collect is empty, taskDispatchNodeId:{}", sendJob.getTaskDispatchNodeId());
191	            updateMessageState(sendJob, MessageRunStateEnum.FAIL);
192	            return ;
193	        }
194	        NoticeTimeTypeEnum enumByValue = NoticeTimeTypeEnum.getEnumByValue(sendJob.getNoticeTimeType());
195	        TaskDispatch taskDispatch = taskDispatchDao.getById(taskDispatchNode.getTaskDispatchId());
196	        for(NMaterialPushCfg cfg : collect) {
197	            message(cfg, taskDispatch, taskDispatchNode,
198	                projectOrderManager.getProjectOrder(taskDispatch.getProjectOrderId()),
199	                enumByValue);
200	        }
201	        updateMessageState(sendJob, MessageRunStateEnum.SUCCESS);
202	    }
