334	                                     NoticeTimeTypeEnum enumByValue) {
335	        if(NoticeTimeTypeEnum.WILL_DELAY.equals(enumByValue)
336	            || NoticeTimeTypeEnum.UNDO_DELAY.equals(enumByValue)) {
