349	    /**
350	     *
351	     *
352	     *
353	     * @param pushCfg
354	     * @param taskDispatch
355	     * @param taskDispatchNode
356	     * @param projectOrder
357	     */
358	    private void message(NMaterialPushCfg pushCfg,
359	                         TaskDispatch taskDispatch,
360	                         TaskDispatchNode taskDispatchNode,
361	                         ProjectOrderDetailBO projectOrder,
362	                         NoticeTimeTypeEnum enumByValue) {
363	        // 获取关联角色
364	        String relationCode = pushCfg.getRelationCode();
365	        if(relationCode.startsWith(otherRoleCode)) {
366	            sendOtherRole(pushCfg, taskDispatch, taskDispatchNode, projectOrder, enumByValue);
367	            return ;
368	        }
369	        Set<Pair<RoleTypeEnum, String>> relationUcId
370	            = getRelationUcId(pushCfg, taskDispatch, taskDispatchNode, projectOrder);
371	        String[] strings = SplitterUtaskCode(relationCode);
372	        List<NMaterialTaskForm> relationTask = materialTaskDao.queryListAllInfo(NMaterialTaskCondition.builder()
373	            .processCode(strings[0]).taskCode(strings[1])
374	            .state(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue().byteValue())
375	            .build());
376	        if(CollectionUtils.isEmpty(relationTask)) {
377	            log.info("relationTask is empty, taskDispatchNodeId:{}, relationCode:{}", taskDispatchNode.getId(), relationCode);
378	            return ;
379	        }
380	        NMaterialTaskForm relationTaskForm = relationTask.get(0);
381	        String roleTypes = relationTaskForm.getRoleTypes();
382	        if(NoticeTimeTypeEnum.RESTART_ACTIVE.equals(enumByValue)) {
383	            roleTypes = relationTaskForm.getRestartRoleTypes();
384	        }
385	        if(StringUtils.isBlank(roleTypes)) {
386	            log.info("roleTypes is empty, taskDispatchNodeId:{}, relationCode:{}", taskDispatchNode.getId(), relationCode);
387	            return ;
388	        }
389	        List<Integer> roleTypeList = RoleTypeUtil.convertRoleTypes(roleTypes);
390	        if(CollectionUtils.isEmpty(roleTypeList)) {
391	            log.info("roleTypeList is empty, taskDispatchNodeId:{}, relationCode:{}", taskDispatchNode.getId(), relationCode);
392	            return ;
393	        }
394	        for(Integer roleType : roleTypeList) {
395	            RoleTypeEnum byValue = RoleTypeEnum.getByValue(roleType);
396	            if(byValue == null) {
397	                log.info("RoleTypeEnum is null, taskDispatchNodeId:{}, relationCode:{}, roleType:{}", taskDispatchNode.getId(), relationCode, roleType);
398	                continue;
399	            }
400	            PushChannelEnum channelEnum = byValue.getChannelEnum();
401	            if(channelEnum == null) {
402	                log.info("PushChannelEnum is null, taskDispatchNodeId:{}, relationCode:{}, roleType:{}", taskDispatchNode.getId(), relationCode, roleType);
403	                continue;
404	            }
405	            TaskMessageParam taskMessageParam
406	                = buildPushParam(taskDispatch, taskDispatchNode, projectOrder, enumByValue, channelEnum);
407	
408	            Set<String> collect = relationUcId.stream().map(t -> t.getValue()).collect(Collectors.toSet());
409	            if (CollectionUtils.isEmpty(collect)) {
