480	    private List<TaskDispatchNode> getRelationTaskDispatch(String relationCode,
481	                                                 Long projectOrderId,
482	                                                 TaskDispatch dispatch) {
483	        TaskDispatchNodeExample example = new TaskDispatchNodeExample();
484	        TaskDispatchNodeExample.Criteria criteria = example.createCriteria();
485	        criteria.andProjectOrderIdEqualTo(projectOrderId).andStateEqualTo(com.ke.utopia.starlord.enumeration.StateEnum.VALID.getValue().byteValue())
486	            .andUTaskCodeIn(Lists.newArrayList(relationCode));
487	        List<TaskDispatchNode> taskNodeList = taskDispatchNodeDao.listByExample(example);
488	        List<TaskDispatchNode> orderNoList = Lists.newArrayList();
489	        List<TaskDispatchNode> otherList = Lists.newArrayList();
490	        for (TaskDispatchNode tempNode : taskNodeList) {
491	            if (!StringUtils.isEmpty(dispatch.getOrderNo()) && tempNode.getOrderNo().equals(dispatch.getOrderNo())) {
492	                orderNoList.add(tempNode);
493	            } else {
494	                otherList.add(tempNode);
495	            }
496	        }
497	        taskNodeList = !CollectionUtils.isEmpty(orderNoList) ? orderNoList : otherList;
498	        log.info("[NewMessagePushServiceImpl]第一次过滤信息:{} " + "优先取品类 + 供应商一致的", taskNodeList);
499	        // 优先取品类 + 供应商一致的
500	        List<TaskDispatchNode> secondFilter = Lists.newArrayList();
501	        for(TaskDispatchNode tempNode : taskNodeList) {
502	            TaskDispatch taskDispatch = taskDispatchDao.getById(tempNode.getTaskDispatchId());
503	            if(Objects.equals(dispatch.getMaterialCode(), taskDispatch.getMaterialCode())
504	                && Objects.equals(dispatch.getSupplierCode(), taskDispatch.getSupplierCode())) {
505	                secondFilter.add(tempNode);
506	            }
507	        }
508	        if(!CollectionUtils.isEmpty(secondFilter)) {
509	            log.info("[SupplierMaterialTaskNodeRelationTypeProcessor]过滤信息:{} " +
510	                "优先取品类 + 供应商一致的", secondFilter);
511	            taskNodeList = secondFilter;
512	        }
513	        return taskNodeList;
514	    }
