537	        String aliasName = NodeTypeEnum.getAliasName(node.getNodeType(), TaskTypeEnum.getNameByValue(taskDispatch.getTaskType()));
538	        context.setVariable("nodeName", aliasName);
539	        context.setVariable("controlModel", projectOrder.getOrderDto().getControlModel());
540	        context.setVariable("progressType", 1);
541	        try {
542	            context.setVariable("title",
543	                URLEncoder.encode(taskDispatch.getSupplierName() + taskDispatch.getMaterialName(),"utf-8"));
544	        } catch (UnsupportedEncodingException e) {
545	            log.info("", e);
546	            context.setVariable("title", "");
547	        }
548	        Config config = ConfigService.getConfig("message");
549	        String jumpUrl = "";
550	        if(PushChannelEnum.RENWUTIXING.equals(channelEnum)) {
551	            jumpUrl = config.getProperty("message.foreman.path", "");
552	        } else {
553	            jumpUrl = config.getProperty("message.home.path", "");
