555	        TaskMessageParam messageParam = TaskMessageParam.builder()
556	            .title(parser.parseExpression(getSpecialTitle(taskDispatch, node, timeTypeEnum), parserContext).getValue(context,String.class))
557	            .content(parser.parseExpression(getSpecialContext(taskDispatch, node, timeTypeEnum), parserContext).getValue(context,String.class))
558	            .url(parser.parseExpression(jumpUrl, parserContext).getValue(context, String.class)).build();
559	        messageParam.setChannel(channelEnum.getCode());
560	
561	        return messageParam;
562	    }
