650	    public static String getRestartNodeName(TaskTypeEnum taskTypeEnum, Integer nodeType) {
651	        String restartNodeName = "";
652	        if(TaskTypeEnum.ORDER_TAKING.equals(taskTypeEnum)) {
653	            restartNodeName = "供应商拒单";
654	        }
655	        if(TaskTypeEnum.ENTER.equals(taskTypeEnum)) {
656	            if(NodeTypeEnum.FINISH_START.getValue().equals(nodeType)) {
657	                restartNodeName = "送货拒收";
658	            }
659	        }
660	        if(TaskTypeEnum.INSTALL.equals(taskTypeEnum)) {
661	            if(NodeTypeEnum.START.getValue().equals(nodeType)) {
662	                restartNodeName = "安装失败";
663	            }
664	            if(NodeTypeEnum.FINISH_START.getValue().equals(nodeType)) {
665	                restartNodeName = "验收报告驳回";
666	            }
667	        }
668	        if(TaskTypeEnum.RECHECK_SCALE.equals(taskTypeEnum)) {
669	            if(NodeTypeEnum.START.getValue().equals(nodeType)) {
670	                restartNodeName = "复尺失败";
671	            }
672	        }
673	        if(TaskTypeEnum.QUOTE.equals(taskTypeEnum)) {
674	            if(NodeTypeEnum.FINISH_START.getValue().equals(nodeType)) {
675	                restartNodeName = "验收报告驳回";
676	            }
677	        }
678	        return restartNodeName;
679	    }
