702	        sendJob.setNoticeMoment(pushCfg.getNoticeMoment());
703	        sendJob.setRunState(MessageRunStateEnum.WAIT.getCode());
704	        if(Integer.valueOf(0).equals(pushCfg.getNoticeParent())) {
705	            sendJob.setParentExecutorId("");
706	            messageSendJobDao.save(sendJob);
707	        } else {
708	            Set<Pair<RoleTypeEnum, String>> relationUcId = getRelationUcId(pushCfg, taskDispatch, taskDispatchNode, detailBO);
709	            if(CollectionUtils.isEmpty(relationUcId)) {
710	                log.info("relationUcId is empty, taskDispatchNodeId:{}, relationCode:{}", taskDispatchNode.getId(), pushCfg.getRelationCode());
711	                return false;
712	            }
713	            Map<Pair<RoleTypeEnum, String>, List<String>> pairListMap = parentUcId(relationUcId);
714	            for(Pair<RoleTypeEnum, String> pair : pairListMap.keySet()) {
715	                List<String> pid = pairListMap.get(pair);
716	                pid.stream().forEach(t -> {
717	                    MessageSendJob newSendJon = new MessageSendJob();
718	                    BeanUtils.copyProperties(sendJob, newSendJon);
719	                    newSendJon.setParentExecutorId(t);
720	                    newSendJon.setParentExecutorType(pair.getLeft().getValue().toString());
721	                    messageSendJobDao.save(newSendJon);
722	                });
723	            }
724	        }
725	        return true;
726	    }
