479	    @Override
480	    public NotifyTaskBatchHandleResultVO batchHandleNotifyTasks(NotifyBatchHandleParam param) {
481	        if (CollectionUtils.isEmpty(param.getTaskDispatchNodeItems())) {
482	            return NotifyTaskBatchHandleResultVO.builder().successCount(0).successList(Collections.emptyList()).failList(Collections.emptyList()).build();
483	        }
484	        logger.info("batchHandleNotifyTasks param: {}", param);
485	        Map<Long, NotifyNodeHandleItem> itemMap = param.getTaskDispatchNodeItems().stream()
486	                .collect(Collectors.toMap(NotifyNodeHandleItem::getTaskDispatchNodeId, Function.identity(), (o1, o2) -> o1));
487	        List<Long> nodeIdList = param.getTaskDispatchNodeItems().stream()
488	                .map(NotifyNodeHandleItem::getTaskDispatchNodeId)
489	                .collect(Collectors.toList());
490	
491	        // 节点
492	        List<TaskDispatchNode> nodes = taskDispatchNodeDao.listByIds(nodeIdList);
493	        Map<Long, TaskDispatchNode> nodeMap = nodes.stream()
494	                .collect(Collectors.toMap(TaskDispatchNode::getId, Function.identity(), (o1, o2) -> o1));
495	        Set<Long> dispatchIds = nodes.stream()
496	                .map(TaskDispatchNode::getTaskDispatchId)
497	                .collect(Collectors.toSet());
498	        // task
499	        List<TaskDispatch> taskDispatches = taskDispatchDao.listByIds(Lists.newArrayList(dispatchIds));
500	        Map<Long, TaskDispatch> dispatchMap = taskDispatches.stream()
501	                .collect(Collectors.toMap(TaskDispatch::getId, Function.identity(), (o1, o2) -> o1));
502	
503	        // 获取推荐
504	        Map<String, MaterialNotifyTaskAutomation> autoMap = queryLatestNotifyUnDoneByDimension2(taskDispatches, DEFAULT_TASK_TYPE);
505	
506	        List<Long> successNodeIds = new ArrayList<>();
507	        List<Long> failedNodeIds = new ArrayList<>();
508	        // 操作员
509	        IOperator operator = OperatorContextHandler.getContext().getOperator();
510	        OperatorDTO operatorDTO = new OperatorDTO();
511	        operatorDTO.setUcid(String.valueOf(operator.getUcid()));
512	        operatorDTO.setUsername(operator.getUsername() + "（一键通知复尺）");
513	
514	        for (TaskDispatchNode node : nodes) {
515	            if (node.getTaskDispatchId() != null
516	                    && ProcessStatusEnum.FINISHED.getValue().equals(node.getProcessStatus().intValue())) {
517	                log.info("batchHandleNotifyTasks skip completed node: {}", node.getId());
518	                continue;
519	            }
520	            try {
521	                MaterialNotifyTaskAutomation auto = autoMap.get(dimensionKey(
522	                        node.getProjectOrderId(),
523	                        dispatchMap.get(node.getTaskDispatchId()).getMaterialCode()));
524	                DispatchHandleParam handleParam = new DispatchHandleParam();
525	                handleParam.setTaskDispatchNodeId(node.getId());
526	                // 图片必须大于等于3张
527	                if (itemMap.get(node.getId()).getImages().size() < 3) {
528	                    logger.warn("batchHandleNotifyTasks skip node {} due to images size < 3", node.getId());
529	                    failedNodeIds.add(node.getId());
530	                    continue;
531	                }
532	                // 设置图片和上门时间
533	                handleParam.setImages(itemMap.get(node.getId()).getImages());
534	                handleParam.setQualified(itemMap.get(node.getId()).getQualified());
535	                handleParam.setRemarks(itemMap.get(node.getId()).getRemarks());
536	                handleParam.setNoticeRetainTime(itemMap.get(node.getId()).getNoticeRetainTime());
537	                materialHandleV2Service.handleNode(handleParam, operatorDTO);
538	
539	                Integer adoptionType = classifyAdoption(auto, new HashSet<>(handleParam.getImages()), handleParam.getNoticeRetainTime());
540	                MaterialNotifyTaskAutomation update = MaterialNotifyTaskAutomation.builder()
541	                        .id(auto.getId())
542	                        .notifyExecuteType(NotifyExecuteTypeEnum.ONE_KEY_NOTIFY.getValue())
543	                        .aiAdoptionType(adoptionType == null ? 0 : adoptionType.byteValue())
544	                        .build();
545	
546	                materialNotifyTaskAutomationDao.updateById(update);
547	                successNodeIds.add(node.getId());
548	            } catch (Exception e) {
549	                failedNodeIds.add(node.getId());
550	                log.error("batchHandleNotifyTasks error: {}", node.getId(), e);
551	            }
552	        }
553	        // 所有节点 ID 列表以及项目 ID 集合
554	        List<Long> allNodeIds = new ArrayList<>(
555	                successNodeIds.size() + failedNodeIds.size());
556	
557	        allNodeIds.addAll(successNodeIds);
558	        allNodeIds.addAll(failedNodeIds);
559	
560	        Set<Long> projectOrderIds = allNodeIds.stream()
561	                .map(nodeMap::get)
562	                .filter(Objects::nonNull)
563	                .map(TaskDispatchNode::getProjectOrderId)
564	                .filter(Objects::nonNull)
565	                .collect(Collectors.toSet());
566	        // 项目订单信息
567	        Map<Long, ProjectOrderDetailBO> projectOrderMap =
568	                fetchProjectOrders(projectOrderIds);
569	        // 构建任务详情,按照项目汇总
570	        List<NotifyTaskDetailVO> successTasks = buildTaskDetails(successNodeIds, nodeMap, dispatchMap);
571	        List<NotifyTaskDetailVO> failedTasks = buildTaskDetails(failedNodeIds, nodeMap, dispatchMap);
572	        List<NotifyTaskProjectGroupVO> failedProjects = groupByProject(failedTasks, projectOrderMap);
573	        List<NotifyTaskProjectGroupVO> successProjects = groupByProject(successTasks, projectOrderMap);
574	
575	        return NotifyTaskBatchHandleResultVO.builder()
576	                .successCount(successNodeIds.size())
577	                .successList(successProjects)
578	                .failList(failedProjects)
579	                .build();
580	    }
