624	        // 2. Apollo 开关 gate（与 filterByFeatureSwitch 同口径：gbCode/工程部取 ProjectOrderDetailBO）
625	        ProjectOrderDetailBO order = fetchProjectOrders(Collections.singleton(projectOrderId)).get(projectOrderId);
626	        String gbCode = order == null ? null : order.getGbCode();
