628	        if (!notifyAutomationConfig.isFeatureOpen(gbCode, executorId, departmentCode)) {
629	            return NotifyTaskAutoFillVO.builder()
630	                    .taskDispatchNodeId(node.getId())
631	                    .projectOrderId(String.valueOf(projectOrderId))
632	                    .taskType(null)
633	                    .images(Collections.emptyList())
634	                    .recommendVisitTime(null)
635	                    .build();
636	        }
637	
638	        // 3. 取 dispatch 拿 taskType + materialCode（taskType 为返回字段必查）
639	        TaskDispatch dispatch = taskDispatchDao.getById(node.getTaskDispatchId());
640	        Integer taskType = dispatch.getTaskType();
641	        String materialCode = dispatch.getMaterialCode();
642	        logger.info("queryNotifyTaskAutoFill nodeId: {}, taskType: {}, materialCode: {}", node.getId(), taskType, materialCode);
