644	        // 4. 先看 node 有没有：node 缺图片或缺上门时间才去查 automation（避免无谓查询）
645	        boolean nodeHasImages = !StringUtils.isEmpty(node.getImages());
646	        Calendar calendar = Calendar.getInstance();
647	        calendar.setTime(node.getNoticeRetainTime());
648	        boolean nodeHasTime = calendar.get(Calendar.YEAR) >= 2010;   // node 时间小于 2010 年视为无效
649	
650	        List<String> images;
651	        Date recommendVisitTime;
652	        if (nodeHasImages || nodeHasTime) {
