666	                .taskDispatchNodeId(node.getId())
667	                .projectOrderId(String.valueOf(projectOrderId))
668	                .taskType(taskType)
669	                .images(images)
670	                .recommendVisitTime(recommendVisitTime)
671	                .build();
672	    }
