709	    /**
710	     * 自动执行通知任务：扫描 automation 表「昨日识别 + 可通知(judge=1) + 未执行(notify_execute_type=0)」候选，
711	     * 维度反查待通知节点（taskType=3 / nodeType=20 / processStatus=2）后，逐件经 autoNotify 开关校验，
712	     * 复用 handleNode 全链路完成通知（images/时间取自 automation 行）。受 notification.remeasure.automation.autoNotify 管控。
713	     */
714	    @Override
715	    public NotifyTaskAutoExecuteResultVO autoExecuteNotifyTasks() {
716	        MaterialNotifyTaskAutomation condition = MaterialNotifyTaskAutomation.builder()
717	                .judgeResult(NotifyJudgeResultEnum.CAN_NOTIFY.getValue().byteValue())
718	                .taskType(DEFAULT_TASK_TYPE)
719	                .build();
720	        List<MaterialNotifyTaskAutomation> candidates = materialNotifyTaskAutomationDao.selectByEntity(condition);
721	        logger.info("autoExecuteNotifyTasks candidates count: {}", candidates.size());
722	        if (CollectionUtils.isEmpty(candidates)) {
723	            return NotifyTaskAutoExecuteResultVO.builder()
724	                    .candidateCount(0).executedCount(0).build();
725	        }
726	
727	        // 2. 维度反查待通知节点（taskType=3 / nodeType=20 / processStatus=2 / 无 executor 即系统级扫描）
728	        List<Long> projectOrderIdList = candidates.stream()
729	                .map(MaterialNotifyTaskAutomation::getProjectOrderId)
730	                .distinct().collect(Collectors.toList());
731	        List<String> materialCodeList = candidates.stream()
732	                .map(MaterialNotifyTaskAutomation::getMaterialCode)
733	                .filter(Objects::nonNull).distinct().collect(Collectors.toList());
734	        TaskDispatchParam nodeParam = new TaskDispatchParam();
735	        nodeParam.setProjectOrderIdList(projectOrderIdList);
736	        nodeParam.setMaterialCodeList(materialCodeList);
737	        nodeParam.setTaskTypeList(Collections.singletonList(DEFAULT_TASK_TYPE));
738	        nodeParam.setNodeTypeList(Collections.singletonList(NOTIFY_NODE_TYPE));
739	        nodeParam.setProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
740	        List<TaskDispatchDTO> nodeList = taskDispatchNodeDao.listTaskByCondition(nodeParam)
741	                .stream().filter(node -> RestartStatusEnum.FIRST.getValue().equals(node.getRestartCount()))
742	                .collect(Collectors.toList());
743	        logger.info("autoExecuteNotifyTasks nodeList count: {}", nodeList.size());
744	
745	        // listTaskByCondition 的 projectOrderIdList / materialCodeList 是独立 IN（AND 语义），
746	        // 会产生 projList × matList 的超集节点；按候选维度精确收敛，避免无关组合进入映射
747	        Map<String, MaterialNotifyTaskAutomation> candidateMap = candidates.stream()
748	                .collect(Collectors.toMap(c -> dimensionKey(c.getProjectOrderId(), c.getMaterialCode()),
749	                        c -> c, (existing, replacement) -> existing));
750	        nodeList = nodeList.stream()
751	                .filter(n -> candidateMap.containsKey(dimensionKey(n.getProjectOrderId(), n.getMaterialCode())))
752	                .collect(Collectors.toList());
753	        Map<String, TaskDispatchDTO> nodeMap = new LinkedHashMap<>();
754	        for (TaskDispatchDTO n : nodeList) {
755	            nodeMap.put(dimensionKey(n.getProjectOrderId(), n.getMaterialCode()), n);
756	        }
757	
758	
759	        OperatorDTO operatorDTO = new OperatorDTO();
760	        operatorDTO.setUsername("系统自动通知复尺");
761	
762	        List<NotifyTaskDetailVO> executedNodes = new ArrayList<>();
763	        Set<Long> nodeProjectIds = new HashSet<>();
764	        nodeList.forEach(n -> nodeProjectIds.add(n.getProjectOrderId()));
765	        Map<Long, ProjectOrderDetailBO> projectOrderMap = fetchProjectOrders(nodeProjectIds);
766	        Integer successCount = 0;
767	        for (TaskDispatchDTO node : nodeList) {
768	            ProjectOrderDetailBO order = projectOrderMap.get(node.getProjectOrderId());
769	            MaterialNotifyTaskAutomation materialNotifyTaskAutomation = candidateMap.get(dimensionKey(node.getProjectOrderId(), node.getMaterialCode()));
770	            if (splitImages(materialNotifyTaskAutomation.getImages()).size() < 3) {
771	                log.warn("autoExecuteNotifyTasks skip node {} due to invalid images", node);
772	                continue;
773	            }
774	            String gbCode = order == null ? null : order.getGbCode();
775	            String departmentCode = resolveDepartmentCode(order);
776	            if (!notifyAutomationConfig.isAutoNotifyOpen(
777	                    node.getMaterialCode(), gbCode, node.getExecutorId(), departmentCode)) {
778	                continue;
779	            }
780	            DispatchHandleParam handleParam = new DispatchHandleParam();
781	            handleParam.setTaskDispatchNodeId(node.getTaskDispatchNodeId());
782	            handleParam.setRemarks("自动通知复尺");
783	            handleParam.setImages(splitImages(materialNotifyTaskAutomation.getImages()));
784	            handleParam.setNoticeRetainTime(materialNotifyTaskAutomation.getRecommendVisitTime());
785	            try {
786	                materialHandleV2Service.handleNode(handleParam, operatorDTO);
787	
788	                MaterialNotifyTaskAutomation update = MaterialNotifyTaskAutomation.builder()
789	                        .id(materialNotifyTaskAutomation.getId())
790	                        .notifyExecuteType(NotifyExecuteTypeEnum.AUTO_NOTIFY.getValue())
791	                        .aiAdoptionType((byte) 1)
792	                        .build();
793	
794	                materialNotifyTaskAutomationDao.updateById(update);
795	                executedNodes.add(NotifyTaskDetailVO.builder()
796	                        .projectOrderId(String.valueOf(node.getProjectOrderId()))
797	                        .taskDispatchNodeId(node.getTaskDispatchNodeId())
798	                        .materialCode(node.getMaterialCode())
799	                        .build());
800	                successCount++;
801	            } catch (Exception e) {
802	                logger.error("autoExecuteNotifyTasks handleNode error", e);
803	            }
804	        }
805	        logger.info("autoExecuteNotifyTasks executed={}/skipped={}/failed={}/total={}/date={}/executedNodes={}",
806	                successCount, 0, 0, candidates.size(), DateUtil.format(new Date(), DateUtil.DEFAULT_DATE_FORMAT), executedNodes);
807	
808	        return NotifyTaskAutoExecuteResultVO.builder()
809	                .candidateCount(candidates.size())
810	                .executedCount(successCount)
811	                .autoNotifyTaskDetailList(executedNodes)
812	                .build();
813	    }
814	
815	    public Integer classifyAdoption(MaterialNotifyTaskAutomation auto, Set<String> confirmedImages,
816	                                    Date confirmedTime) {
817	        if (auto == null || StringUtils.isEmpty(auto.getImages())) {
818	            return null;
819	        }
820	        Set<String> autoImages = new HashSet<>(splitImages(auto.getImages()));
821	        boolean imgSame = autoImages.equals(confirmedImages) && confirmedImages.containsAll(autoImages);
822	        boolean timeSame = auto.getRecommendVisitTime() != null && confirmedTime != null
823	                && auto.getRecommendVisitTime().getTime() == confirmedTime.getTime();
824	        if (imgSame && timeSame) {
825	            return AiAdoptionTypeEnum.ACCEPTED.getCode();
826	        }
827	        if (!imgSame && !timeSame) {
828	            return AiAdoptionTypeEnum.NOT_ACCEPTED.getCode();
829	        }
830	        return imgSame ? AiAdoptionTypeEnum.IMAGE_ACCEPTED.getCode() : AiAdoptionTypeEnum.VISIT_TIME_ACCEPTED.getCode();
831	    }
832	}
